import{_ as i,o as t,c as s,a4 as e}from"./chunks/framework.BRqpndjL.js";const g=JSON.parse('{"title":"我的 Vibe Coding 工作流","description":"用 AI 写代码最容易翻车的地方不是代码质量，而是需求没想清楚。这是我迭代了半年后固定下来的六步流程。","frontmatter":{"title":"我的 Vibe Coding 工作流","date":"2025-02-16T00:00:00.000Z","tags":["Vibe Coding","方法论","AI"],"description":"用 AI 写代码最容易翻车的地方不是代码质量，而是需求没想清楚。这是我迭代了半年后固定下来的六步流程。","readingTime":8},"headers":[],"relativePath":"blog/posts/vibe-coding-workflow.md","filePath":"blog/posts/vibe-coding-workflow.md","lastUpdated":1791616398000}'),l={name:"blog/posts/vibe-coding-workflow.md"};function n(o,a,r,d,p,h){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="我的-vibe-coding-工作流" tabindex="-1">我的 Vibe Coding 工作流 <a class="header-anchor" href="#我的-vibe-coding-工作流" aria-label="Permalink to &quot;我的 Vibe Coding 工作流&quot;">​</a></h1><p>半年时间我用 AI 辅助做了十几个小项目，从「生成的代码跑不起来」到「一个周末能上线一个工具」，中间踩的坑大多不是技术问题，而是<strong>流程问题</strong>。</p><p>这篇文章记录我目前固定下来的六步流程。</p><h2 id="第一步-先写「完成定义」-再动手" tabindex="-1">第一步：先写「完成定义」，再动手 <a class="header-anchor" href="#第一步-先写「完成定义」-再动手" aria-label="Permalink to &quot;第一步：先写「完成定义」，再动手&quot;">​</a></h2><p>这是最容易被跳过、但收益最大的一步。动手之前我会先用三句话写清楚：</p><ul><li><strong>谁用</strong>：只有我自己用，还是要给别人用？（决定要不要做登录、要不要考虑多设备）</li><li><strong>最小可用是什么</strong>：能完成一次完整闭环的最少功能是什么？</li><li><strong>什么算做完了</strong>：一句可以验证的话，比如「能把一段文字粘贴进去，导出一份 Markdown 文件」</li></ul><div class="warning custom-block"><p class="custom-block-title">别跳过这一步</p><p>我至少有三四个项目是在写到一半时发现「我其实不需要这个功能」，然后全部推倒重来。写三句话只要五分钟。</p></div><h2 id="第二步-让-ai-搭骨架-不要一次写完" tabindex="-1">第二步：让 AI 搭骨架，不要一次写完 <a class="header-anchor" href="#第二步-让-ai-搭骨架-不要一次写完" aria-label="Permalink to &quot;第二步：让 AI 搭骨架，不要一次写完&quot;">​</a></h2><p>我一开始的坏习惯是让 AI「帮我写一个完整的番茄钟应用」。结果通常是得到一个 800 行的单文件，能跑，但完全不敢改。</p><p>现在我会拆成三轮：</p><table tabindex="0"><thead><tr><th>轮次</th><th>目标</th><th>产出</th></tr></thead><tbody><tr><td>第一轮</td><td>能跑起来的空壳</td><td>页面结构 + 假数据</td></tr><tr><td>第二轮</td><td>一条真实数据链路</td><td>能读能写，忽略样式</td></tr><tr><td>第三轮</td><td>体验打磨</td><td>加载态、错误态、动效</td></tr></tbody></table><p>每一轮结束我都会<strong>自己运行一次</strong>，确认没问题再进入下一轮。</p><h2 id="第三步-把「判断」留给自己" tabindex="-1">第三步：把「判断」留给自己 <a class="header-anchor" href="#第三步-把「判断」留给自己" aria-label="Permalink to &quot;第三步：把「判断」留给自己&quot;">​</a></h2><p>AI 最容易出错的地方不是语法，而是<strong>取舍</strong>：</p><ul><li>用不用第三方库？</li><li>状态放组件里还是全局？</li><li>这个功能要不要做？</li></ul><p>这些问题我不会直接问「你觉得呢」，而是给出约束再让它对比：</p><blockquote><p>我要在纯前端做本地存储，数据量大概几百条。用 IndexedDB 和 localStorage 各自的代价是什么？请用表格对比，不要给建议。</p></blockquote><p>拿到对比之后<strong>我自己决定</strong>。这样即使后来发现选错了，我也知道为什么错。</p><h2 id="第四步-小步提交-方便回滚" tabindex="-1">第四步：小步提交，方便回滚 <a class="header-anchor" href="#第四步-小步提交-方便回滚" aria-label="Permalink to &quot;第四步：小步提交，方便回滚&quot;">​</a></h2><p>用 AI 写代码时，代码变化的速度远快于手写，所以版本控制更重要：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;feat: 完成粘贴文本解析&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>我喜欢在每次「AI 改完并且我验证通过」之后立刻提交一次。这样当下一轮 AI 把东西改坏时，我可以直接：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>而不是花半小时回忆哪里被改了。</p><h2 id="第五步-让-ai-做代码审查" tabindex="-1">第五步：让 AI 做代码审查 <a class="header-anchor" href="#第五步-让-ai-做代码审查" aria-label="Permalink to &quot;第五步：让 AI 做代码审查&quot;">​</a></h2><p>功能做完之后，我会把关键文件丢回去让 AI 审查，但<strong>换一种提问方式</strong>：</p><blockquote><p>请以代码审查者的身份看这个文件，重点找：1) 边界条件没处理的地方 2) 没有意义的抽象 3) 我可能误解的 API 用法。不要夸奖，直接列问题。</p></blockquote><p>这个提问方式比「帮我优化一下」有用得多，因为后者通常只会得到一些无关痛痒的重命名建议。</p><h2 id="第六步-写完立刻写记录" tabindex="-1">第六步：写完立刻写记录 <a class="header-anchor" href="#第六步-写完立刻写记录" aria-label="Permalink to &quot;第六步：写完立刻写记录&quot;">​</a></h2><p>我会在项目刚做完、还记得所有细节的时候写一篇记录，最少包含三件事：</p><ol><li>为什么做这个（真实痛点）</li><li>最花时间的一个技术点</li><li>如果重做，我会怎么做</li></ol><p>这个习惯的价值在几个月后才体现出来：当我遇到类似问题时，翻自己的记录比搜索快得多。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>❌ <strong>把 AI 当搜索引擎</strong>：问「怎么做 X」得到的是通用答案，问「在我的代码里怎么改」才有用</li><li>❌ <strong>一次改太多</strong>：一轮改三个功能，出问题很难定位</li><li>❌ <strong>不运行就继续</strong>：生成的代码看起来对，实际报错的位置可能离你以为的很远</li><li>✅ <strong>把上下文给足</strong>：相关文件、错误信息、你的约束，一起给它</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>如果只留一条建议，那就是：<strong>AI 负责写，你负责判断</strong>。判断的质量决定了项目能走多远，而判断力只能靠一次次真实地运行、观察、修正来积累。</p>`,36)])])}const b=i(l,[["render",n]]);export{g as __pageData,b as default};
